\label{prop:planar}
	There are $C^\infty$ regular embeddings $P,Q:\mathbb T\to\mathbb R^2$ and a smooth function $f:\mathbb T\to(0,\infty)$ such that
	\[
		Q'=fP',\qquad\int_0^{24}\det(Q(t),P'(t))dt=0.\refstepcounter{equation}\tag{\theequation}\label{eq:planar-data}
	\]

\label{prop:annulus}
	Let $P,Q:\mathbb T\to\mathbb R^2$ be smooth regular embeddings satisfying~\eqref{eq:planar-data}. Define
	\[
		z(t)=\int_0^t\det(Q(s),P'(s))ds,\qquad\gamma(t)=(P(t),z(t)),\qquad n(t)=\frac{(-JQ(t),1)}{\sqrt{1+|Q(t)|^2}}.\refstepcounter{equation}\tag{\theequation}\label{eq:lift}
	\]
	Set $v=|\gamma'|$, $T=\gamma'/v$, and $\nu=n\times T$. For some $a>0$, the ruled map
	\[
		F(t,u)=\gamma(t)+u\nu(t)\refstepcounter{equation}\tag{\theequation}\label{eq:ruled-surface}
	\]
	embeds $\mathbb T\times[-a,a]$. Its open annulus has strictly negative Gaussian curvature and an injective Gauss map agreeing with $n$ along $\gamma$, and $\gamma$ is asymptotic.

\label{add:cor:graph}
	Let $P,Q,f$ be the data in Proposition \ref{prop:planar}, and let $z$ be defined by \eqref{eq:lift}. After restricting the annulus in Proposition \ref{prop:annulus}, there are a bounded planar annulus $\Omega\subset\mathbb R^2$ containing $P(\mathbb T)$ and a function $h\in C^\infty(\Omega)$ such that
	\[
		M=\{(x,h(x)):x\in\Omega\},\qquad\det D^2h<0\quad\text{on }\Omega,
	\]
	and $\nabla h:\Omega\to\mathbb R^2$ is injective. Along the core,
	\[
		\begin{aligned}
			h(P(t))&=z(t),&\nabla h(P(t))&=JQ(t),\\
			D^2h(P(t))P'(t)&=f(t)JP'(t),&\det D^2h(P(t))&=-f(t)^2.
		\end{aligned}
		\refstepcounter{equation}\tag{\theequation}\label{add:eq:graph-data}
	\]
